import{_ as n,C as s,o as a,c as i,a2 as r,E as o}from"./chunks/framework.BSaF8iZ6.js";const f=JSON.parse('{"title":"Order Management","description":"","frontmatter":{},"headers":[],"relativePath":"orders/order-management.md","filePath":"orders/order-management.md","lastUpdated":1789411447000}'),d={name:"orders/order-management.md"};function l(h,e,c,g,m,p){const t=s("ImagePopup");return a(),i("div",null,[e[0]||(e[0]=r('<h1 id="order-management" tabindex="-1">Order Management <a class="header-anchor" href="#order-management" aria-label="Permalink to &quot;Order Management&quot;">​</a></h1><div class="page-roles"><span class="role role--seller">Seller</span><span class="role role--admin">Admin</span></div><p>A customer can buy from several sellers in one checkout. Once the order is placed, it is split so that each seller sees and handles only their own products. This page covers how sellers work through their orders and what the admin sees.</p><h2 id="how-a-marketplace-order-works" tabindex="-1">How a marketplace order works <a class="header-anchor" href="#how-a-marketplace-order-works" aria-label="Permalink to &quot;How a marketplace order works&quot;">​</a></h2><ol><li>The customer pays the store for the whole order.</li><li>The order is split, one part for each seller whose products are in it.</li><li>The store&#39;s commission is worked out for each product.</li><li>Each seller invoices and ships their part.</li><li>When their part is complete, the seller requests payment for it.</li></ol><h2 id="your-orders" tabindex="-1">Your orders <a class="header-anchor" href="#your-orders" aria-label="Permalink to &quot;Your orders&quot;">​</a></h2><p>Go to <strong>Sales &gt;&gt; Orders</strong> in the Seller Panel.</p>',7)),o(t,{src:"/images/order-management/orders-list.png",alt:"The seller's Orders list"}),e[1]||(e[1]=r('<p>Each row shows:</p><ul><li><strong>Id / Date / Status / Customer</strong> — the order number and date, the status of your part of the order, and the customer&#39;s name, email and location;</li><li><strong>Items / Payment / Shipment</strong> — how many products, the payment method and the shipping method;</li><li><strong>Gross Amt. / Discount / Commission</strong> — the value of your products, the discount and the store&#39;s commission;</li><li><strong>Seller Earn / Seller Payment Status</strong> — what you earn from the order, and where its payment stands. The payment status is shown only with the <strong>Payment Request</strong> permission. See <a href="./../payments/payment-management#payment-statuses">Payment statuses</a>.</li></ul><p>The buttons on a row show what the order needs next: <strong>Schedule Pickup</strong>, <strong>Print Label</strong>, <strong>Request Payment</strong>, <strong>Transaction</strong> or <strong>View Order</strong>.</p><p>The customer&#39;s email and location are masked when the store doesn&#39;t let sellers see customer details.</p><h3 id="order-statuses" tabindex="-1">Order statuses <a class="header-anchor" href="#order-statuses" aria-label="Permalink to &quot;Order statuses&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>What it means</th></tr></thead><tbody><tr><td><strong>Pending</strong></td><td>The order has just been placed.</td></tr><tr><td><strong>Processing</strong></td><td>Some of your products are invoiced, shipped, cancelled or refunded.</td></tr><tr><td><strong>Completed</strong></td><td>All your products that weren&#39;t cancelled or refunded are invoiced and shipped. A part with any refund stays <strong>Processing</strong>.</td></tr><tr><td><strong>Canceled</strong></td><td>All your products in the order are cancelled.</td></tr><tr><td><strong>Closed</strong></td><td>All your products are refunded or cancelled.</td></tr></tbody></table><h2 id="view-an-order" tabindex="-1">View an order <a class="header-anchor" href="#view-an-order" aria-label="Permalink to &quot;View an order&quot;">​</a></h2><ol><li>Go to <strong>Sales &gt;&gt; Orders</strong>.</li><li>Click <strong>View Order</strong> on the order.</li></ol>',8)),o(t,{src:"/images/order-management/order-view.png",alt:"The seller's view of an order"}),e[2]||(e[2]=r('<p>The <strong>Information</strong> tab lists your products with their price, what has been ordered, invoiced, shipped, refunded and cancelled, and each product&#39;s subtotal. Click the info icon next to a subtotal to see its discount, the store&#39;s commission and the tax.</p><p>Below the products are the order totals, including <strong>Total Seller Amount</strong> and <strong>Admin Commission</strong>. When the store lets sellers see customer details, the billing and shipping addresses and the shipping and payment methods are shown too.</p><p>The <strong>Invoices</strong>, <strong>Shipments</strong> and <strong>Refunds</strong> tabs appear once there is something to show.</p><h2 id="create-an-invoice" tabindex="-1">Create an invoice <a class="header-anchor" href="#create-an-invoice" aria-label="Permalink to &quot;Create an invoice&quot;">​</a></h2><ol><li>Open the order with <strong>View Order</strong>.</li><li>Click <strong>Invoice</strong>.</li><li>In <strong>Create Invoice</strong>, enter the quantity to invoice for each product. You can invoice part of the quantity, but at least one quantity must be more than 0.</li><li>Click <strong>Create Invoice</strong>.</li></ol>',5)),o(t,{src:"/images/order-management/create-invoice.png",alt:"The Create Invoice dialog"}),e[3]||(e[3]=r('<p>You&#39;ll see <strong>Invoice created successfully</strong>. To download an invoice, open the <strong>Invoices</strong> tab and click <strong>Print</strong>.</p><h2 id="ship-the-order" tabindex="-1">Ship the order <a class="header-anchor" href="#ship-the-order" aria-label="Permalink to &quot;Ship the order&quot;">​</a></h2><p>Click <strong>Schedule Pickup</strong> on the order row or on the order page. See <a href="./fulfilment-carriers">Shipments &amp; Carriers</a>.</p><h2 id="cancel-your-part-of-an-order" tabindex="-1">Cancel your part of an order <a class="header-anchor" href="#cancel-your-part-of-an-order" aria-label="Permalink to &quot;Cancel your part of an order&quot;">​</a></h2><ol><li>Open the order with <strong>View Order</strong>.</li><li>Click <strong>Cancel</strong>.</li><li>Confirm.</li></ol><p>Your products that aren&#39;t invoiced yet are cancelled and their stock is returned. Invoiced products can&#39;t be cancelled; the store admin refunds them instead. The customer receives an <strong>Order Cancellation Confirmation</strong> email, with a copy to you and the store admin. The customer&#39;s whole order is cancelled only once every seller&#39;s products in it are cancelled.</p><p>Cancelled products count towards your cancellation rate in <a href="./../sellers/seller-account-health">Account Health</a>.</p><h2 id="refunds" tabindex="-1">Refunds <a class="header-anchor" href="#refunds" aria-label="Permalink to &quot;Refunds&quot;">​</a></h2><p>Sellers can&#39;t refund an order. The store admin issues refunds, and they then appear on the order&#39;s <strong>Refunds</strong> tab.</p><p>After any refund, even a partial one, the order&#39;s <strong>Seller Payment Status</strong> shows <strong>Refunded</strong>, and the order can no longer be requested for payment.</p><h2 id="get-paid" tabindex="-1">Get paid <a class="header-anchor" href="#get-paid" aria-label="Permalink to &quot;Get paid&quot;">​</a></h2><p>When your part of an order is <strong>Completed</strong>, click <strong>Request Payment</strong> on its row. See <a href="./../payments/payment-management">Payment Requests &amp; Payouts</a>.</p><h2 id="emails" tabindex="-1">Emails <a class="header-anchor" href="#emails" aria-label="Permalink to &quot;Emails&quot;">​</a></h2><ul><li>You receive a <strong>New Order Confirmation</strong> email for every new order with your products.</li><li>The customer receives a cancellation email when you cancel.</li><li>When the store sends shipment emails, the contact email of the inventory source you ship from receives a <strong>New Shipment Confirmation</strong> email.</li></ul><p>You don&#39;t receive emails for invoices or refunds.</p><h2 id="for-the-admin" tabindex="-1">For the admin <a class="header-anchor" href="#for-the-admin" aria-label="Permalink to &quot;For the admin&quot;">​</a></h2><p>Go to <strong>Marketplace &gt;&gt; Sales &gt;&gt; Orders</strong> to see every seller&#39;s part of every order. An order with products from two sellers has two rows. Each row shows the order, the customer, the amounts and commission, and the <strong>Shop</strong>, <strong>Seller</strong> and <strong>Earn</strong>.</p>',17)),o(t,{src:"/images/order-management/admin-orders.png",alt:"Seller orders in the admin panel"}),e[4]||(e[4]=r('<p>Click the view icon to open the whole order in <strong>Sales &gt;&gt; Orders</strong>. There you can invoice, ship and refund the order as usual. When you ship a seller&#39;s products, only that seller&#39;s inventory sources are offered. Invoices, shipments and refunds you create there also appear in the seller&#39;s view.</p><h2 id="settings-and-permissions" tabindex="-1">Settings and permissions <a class="header-anchor" href="#settings-and-permissions" aria-label="Permalink to &quot;Settings and permissions&quot;">​</a></h2><ul><li><strong>Can Create Invoice</strong>, <strong>Can Create Shipment</strong>, <strong>Can Cancel Order</strong> and <strong>Can View Customers</strong> in <a href="./../configuration/sellers">Sellers settings</a> decide which buttons and details sellers see.</li><li>Team members need <strong>Orders</strong>, with <strong>View</strong>, <strong>Cancel</strong>, <strong>Invoice</strong>, <strong>Print Invoice</strong>, <strong>Shipment</strong> and <strong>Payment Request</strong> as needed.</li><li>Admins need <strong>Marketplace &gt;&gt; Sales &gt;&gt; Orders</strong> to see the list, and <strong>Sales &gt;&gt; Orders</strong> with <strong>View</strong> to open an order.</li></ul>',3))])}const w=n(d,[["render",l]]);export{f as __pageData,w as default};
